values
  ((select id from w), 'recall', 'Fill in the missing word: Matthew 1:1 traces Jesus''s genealogy through David and back to whom?', 'Matthew 1:1', 'The book of the genealogy of Jesus Christ, the son of David, the son of Abraham.', 'WEB', 1,
   '{"type": "recall", "template": "The book of the genealogy of Jesus Christ, the son of David, the son of ___.", "answer": "Abraham"}', false, 1),
  ((select id from w), 'multiple_choice', 'According to Matthew 1:17, how many generations does Matthew count from Abraham to David?', 'Matthew 1:17', 'So all the generations from Abraham to David are fourteen generations; from David to the exile to Babylon fourteen generations; and from the carrying away to Babylon to the Christ, fourteen generations.', 'WEB', 2,
   '{"type": "multiple_choice", "options": ["Fourteen", "Seven", "Forty", "Twelve"], "correct_index": 0}', false, 2),
  ((select id from w), 'recall', 'Fill in the missing word: what name does the angel tell Joseph to give Mary''s son?', 'Matthew 1:20-21', 'But when he thought about these things, behold, an angel of the Lord appeared to him in a dream, saying, ''Joseph, son of David, don''t be afraid to take to yourself Mary as your wife, for that which is conceived in her is of the Holy Spirit. She shall give birth to a son. You shall name him Jesus, for it is he who shall save his people from their sins.''', 'WEB', 1,
   '{"type": "recall", "template": "But when he thought about these things, behold, an angel of the Lord appeared to him in a dream, saying, ''Joseph, son of David, don''t be afraid to take to yourself Mary as your wife, for that which is conceived in her is of the Holy Spirit. She shall give birth to a son. You shall name him ___, for it is he who shall save his people from their sins.''", "answer": "Jesus"}', false, 3),
  ((select id from w), 'recall', 'Fill in the missing word: what name does Matthew say the child would be called, meaning "God with us"?', 'Matthew 1:22-23', 'Now all this has happened that it might be fulfilled which was spoken by the Lord through the prophet, saying, ''Behold, the virgin shall be with child, and shall give birth to a son. They shall call his name Immanuel,'' which is, being interpreted, ''God with us.''', 'WEB', 2,
   '{"type": "recall", "template": "Now all this has happened that it might be fulfilled which was spoken by the Lord through the prophet, saying, ''Behold, the virgin shall be with child, and shall give birth to a son. They shall call his name ___,'' which is, being interpreted, ''God with us.''", "answer": "Immanuel"}', false, 4),
  ((select id from w), 'multiple_choice', 'According to Matthew 2:1-2, what were the wise men from the east seeking when they came to Jerusalem?', 'Matthew 2:1-2', 'Now when Jesus was born in Bethlehem of Judea in the days of King Herod, behold, wise men from the east came to Jerusalem, saying, ''Where is he who is born King of the Jews? For we saw his star in the east, and have come to worship him.''', 'WEB', 2,
   '{"type": "multiple_choice", "options": ["He who is born King of the Jews", "The high priest of the temple", "A new star to chart", "The governor of Judea"], "correct_index": 0}', false, 5),
  ((select id from w), 'recall', 'Fill in the missing word: besides gold and frankincense, what third gift did the magi offer?', 'Matthew 2:11', 'They came into the house and saw the young child with Mary, his mother, and they fell down and worshiped him. Opening their treasures, they offered to him gifts: gold, frankincense, and myrrh.', 'WEB', 1,
   '{"type": "recall", "template": "They came into the house and saw the young child with Mary, his mother, and they fell down and worshiped him. Opening their treasures, they offered to him gifts: gold, frankincense, and ___.", "answer": "myrrh"}', false, 6),
  ((select id from w), 'multiple_choice', 'According to Matthew 2:13, where did the angel tell Joseph to flee with Mary and the young child?', 'Matthew 2:13', 'Now when they had departed, behold, an angel of the Lord appeared to Joseph in a dream, saying, ''Arise and take the young child and his mother, and flee into Egypt, and stay there until I tell you, for Herod will seek the young child to destroy him.''', 'WEB', 2,
   '{"type": "multiple_choice", "options": ["Egypt", "Babylon", "Damascus", "Cyprus"], "correct_index": 0}', false, 7),
  ((select id from w), 'recall', 'Fill in the missing word: what does Matthew quote the prophet as saying about where God''s son was called from?', 'Matthew 2:15', 'and was there until the death of Herod, that it might be fulfilled which was spoken by the Lord through the prophet, saying, ''Out of Egypt I called my son.''', 'WEB', 2,
