  ((select id from w), 'recall', 'Fill in the missing word: who does Matthew''s fulfillment quotation say was weeping for her children?', 'Matthew 2:17-18', 'Then that which was spoken by Jeremiah the prophet was fulfilled, saying, ''A voice was heard in Ramah, lamentation, weeping and great mourning, Rachel weeping for her children; she wouldn''t be comforted, because they are no more.''', 'WEB', 3,
   '{"type": "recall", "template": "Then that which was spoken by Jeremiah the prophet was fulfilled, saying, ''A voice was heard in Ramah, lamentation, weeping and great mourning, ___ weeping for her children; she wouldn''t be comforted, because they are no more.''", "answer": "Rachel"}', false, 9),
  ((select id from w), 'recall', 'Fill in the missing word: what does Matthew say was fulfilled when Joseph settled the family in Nazareth?', 'Matthew 2:22-23', 'But when he heard that Archelaus was reigning over Judea in the place of his father, Herod, he was afraid to go there. Being warned in a dream, he withdrew into the region of Galilee, and came and lived in a city called Nazareth; that it might be fulfilled which was spoken through the prophets that he will be called a Nazarene.', 'WEB', 3,
   '{"type": "recall", "template": "But when he heard that Archelaus was reigning over Judea in the place of his father, Herod, he was afraid to go there. Being warned in a dream, he withdrew into the region of Galilee, and came and lived in a city called Nazareth; that it might be fulfilled which was spoken through the prophets that he will be called a ___.", "answer": "Nazarene"}', false, 10),
  ((select id from w), 'recall', 'Fill in the missing word: what did John the Baptizer preach in the wilderness of Judea?', 'Matthew 3:1-2', 'In those days, John the Baptizer came, preaching in the wilderness of Judea, saying, ''Repent, for the Kingdom of Heaven is at hand!''', 'WEB', 1,
   '{"type": "recall", "template": "In those days, John the Baptizer came, preaching in the wilderness of Judea, saying, ''___, for the Kingdom of Heaven is at hand!''", "answer": "Repent"}', false, 11),
  ((select id from w), 'multiple_choice', 'According to Matthew 3:13-15, why does Jesus insist John baptize him, even though John objects?', 'Matthew 3:13-15', 'Then Jesus came from Galilee to the Jordan to John, to be baptized by him. But John would have hindered him, saying, ''I need to be baptized by you, and you come to me?'' But Jesus, answering, said to him, ''Allow it now, for this is the fitting way for us to fulfill all righteousness.'' Then he allowed him.', 'WEB', 3,
   '{"type": "multiple_choice", "options": ["To fulfill all righteousness", "To satisfy Roman law", "To prove John''s authority", "To complete his forty days of fasting"], "correct_index": 0}', false, 12),
  ((select id from w), 'recall', 'Fill in the missing word: what does the voice from heaven call Jesus at his baptism?', 'Matthew 3:16-17', 'Jesus, when he was baptized, went up directly from the water: and behold, the heavens were opened to him. He saw the Spirit of God descending as a dove, and coming on him. Behold, a voice out of the heavens said, ''This is my beloved Son, with whom I am well pleased.''', 'WEB', 2,
   '{"type": "recall", "template": "Jesus, when he was baptized, went up directly from the water: and behold, the heavens were opened to him. He saw the Spirit of God descending as a dove, and coming on him. Behold, a voice out of the heavens said, ''This is my ___ Son, with whom I am well pleased.''", "answer": "beloved"}', false, 13),
  ((select id from w), 'recall', 'Fill in the missing word: how many days did Jesus fast in the wilderness?', 'Matthew 4:1-2', 'Then Jesus was led up by the Spirit into the wilderness to be tempted by the devil. When he had fasted forty days and forty nights, he was hungry afterward.', 'WEB', 1,
   '{"type": "recall", "template": "Then Jesus was led up by the Spirit into the wilderness to be tempted by the devil. When he had fasted ___ days and forty nights, he was hungry afterward.", "answer": "forty"}', false, 14),
  ((select id from w), 'recall', 'Fill in the missing word: what does Jesus say man shall not live by alone?', 'Matthew 4:4', 'But he answered, ''It is written, "Man shall not live by bread alone, but by every word that proceeds out of God''s mouth."''', 'WEB', 2,
