  ((select id from w), 'multiple_choice', 'According to Matthew 4:10, what does Jesus tell the devil to do, quoting Deuteronomy?', 'Matthew 4:10', 'Then Jesus said to him, ''Get behind me, Satan! For it is written, "You shall worship the Lord your God, and you shall serve him only."''', 'WEB', 2,
