  ((select id from w), 'recall', 'Fill in the missing word: what does Matthew''s fulfillment quotation say the people sitting in darkness saw?', 'Matthew 4:14-16', 'that it might be fulfilled which was spoken through Isaiah the prophet, saying, ''The land of Zebulun and the land of Naphtali... Galilee of the Gentiles, the people who sat in darkness saw a great light; to those who sat in the region and shadow of death, to them light has dawned.''', 'WEB', 3,
