  ((select id from w), 'recall', 'Fill in the missing word: what "Good News" did Jesus preach as he went through Galilee?', 'Matthew 4:23', 'Jesus went about in all Galilee, teaching in their synagogues, preaching the Good News of the Kingdom, and healing every disease and every sickness among the people.', 'WEB', 1,
