  ((select id from w), 'recall', 'Fill in the missing word: according to the Beatitudes, what will those who mourn be?', 'Matthew 5:3-5', 'Blessed are the poor in spirit, for theirs is the Kingdom of Heaven. Blessed are those who mourn, for they shall be comforted. Blessed are the gentle, for they shall inherit the earth.', 'WEB', 1,
