  ((select id from w), 'recall', 'Fill in the missing word: according to the Beatitudes, what will the pure in heart see?', 'Matthew 5:6-9', 'Blessed are those who hunger and thirst for righteousness, for they shall be filled. Blessed are the merciful, for they shall obtain mercy. Blessed are the pure in heart, for they shall see God. Blessed are the peacemakers, for they shall be called children of God.', 'WEB', 2,
