  ((select id from w), 'recall', 'Fill in the missing word: what does Jesus call his disciples, "of the earth"?', 'Matthew 5:13', 'You are the salt of the earth, but if the salt has lost its flavor, with what will it be salted? It is then good for nothing, but to be cast out and trodden under the feet of men.', 'WEB', 1,
