  ((select id from w), 'multiple_choice', 'According to Matthew 5:14-16, what does Jesus call his disciples, alongside "the salt of the earth"?', 'Matthew 5:14-16', 'You are the light of the world. A city located on a hill can''t be hidden... let your light shine before men, that they may see your good works and glorify your Father who is in heaven.', 'WEB', 2,
