  ((select id from w), 'recall', 'Fill in the missing word: Jesus says he did not come to destroy the Law, but to do what?', 'Matthew 5:17', 'Don''t think that I came to destroy the law or the prophets. I didn''t come to destroy, but to fulfill.', 'WEB', 1,
