  ((select id from w), 'recall', 'Fill in the missing word: in the Lord''s Prayer, what kind of bread do we ask God to give us today?', 'Matthew 6:9-13', 'Pray like this: ''Our Father in heaven, may your name be kept holy. Let your Kingdom come. Let your will be done on earth as it is in heaven. Give us today our daily bread. Forgive us our debts, as we also forgive our debtors. Bring us not into temptation, but deliver us from the evil one. For yours is the Kingdom, the power, and the glory forever. Amen.''', 'WEB', 1,
   '{"type": "recall", "template": "Pray like this: ''Our Father in heaven, may your name be kept holy. Let your Kingdom come. Let your will be done on earth as it is in heaven. Give us today our ___ bread. Forgive us our debts, as we also forgive our debtors. Bring us not into temptation, but deliver us from the evil one. For yours is the Kingdom, the power, and the glory forever. Amen.''", "answer": "daily"}', true, 29),
  ((select id from w), 'recall', 'Fill in the missing word: who does Jesus say feeds the birds of the sky?', 'Matthew 6:26', 'See the birds of the sky, that they don''t sow, neither do they reap, nor gather into barns. Your heavenly Father feeds them. Aren''t you of much more value than they?', 'WEB', 1,
