  ((select id from w), 'recall', 'Fill in the missing word: the Golden Rule says to do to others whatever you desire men to do to whom?', 'Matthew 7:12', 'Therefore, whatever you desire for men to do to you, you shall also do to them; for this is the law and the prophets.', 'WEB', 1,
