  ((select id from w), 'recall', 'Fill in the missing word: what happened to the leper''s leprosy immediately after Jesus touched him?', 'Matthew 8:2-3', 'Behold, a leper came to him and worshiped him, saying, ''Lord, if you want to, you can make me clean.'' Jesus stretched out his hand and touched him, saying, ''I want to. Be made clean.'' Immediately his leprosy was cleansed.', 'WEB', 1,
