  ((select id from w), 'multiple_choice', 'According to Matthew 9:6, what does Jesus tell the paralyzed man to do, to demonstrate the Son of Man''s authority to forgive sins?', 'Matthew 9:6', '''But that you may know that the Son of Man has authority on earth to forgive sins'' — (then he said to the paralytic) — ''Get up, and take up your mat, and go to your house.''', 'WEB', 3,
